import csv
import io
import re

def parse_csv(raw_csv: str):
    expected_width = 9
    if not raw_csv:
        return {"columns": [], "rows": []}

    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    try:
        parsed = list(csv.reader(
            io.StringIO(raw_csv, newline=""),
            delimiter=",",
            quotechar='"',
            doublequote=True,
            strict=False
        ))
    except csv.Error:
        parsed = []
        for line in raw_csv.splitlines():
            try:
                parsed.append(next(csv.reader(
                    [line],
                    delimiter=",",
                    quotechar='"',
                    doublequote=True,
                    strict=False
                )))
            except csv.Error:
                parsed.append(line.split(","))

    records = []
    for row in parsed:
        if not row or all(str(value).strip() == "" for value in row):
            continue
        records.append([str(value) for value in row])

    if not records:
        return {"columns": [], "rows": []}

    header_index = None
    for index, row in enumerate(records):
        if len(row) == expected_width:
            header_index = index
            break

    if header_index is None:
        header_index = 0

    header = records[header_index][:]

    def text_header_index():
        patterns = (
            "description", "comment", "note", "remark", "text",
            "details", "detail", "message", "summary", "title",
            "name", "address", "location"
        )
        for index, value in enumerate(header):
            normalized = re.sub(r"[^a-z0-9]+", "", value.lower())
            if any(pattern in normalized for pattern in patterns):
                return index
        return expected_width - 1

    def fit_row(row, width):
        if len(row) == width:
            return row[:]
        if len(row) < width:
            return row[:] + [""] * (width - len(row))

        merge_at = text_header_index()
        if merge_at >= width:
            merge_at = width - 1

        excess = len(row) - width
        end = merge_at + excess + 1
        merged = row[merge_at:end]
        result = row[:merge_at] + [",".join(merged)] + row[end:]
        if len(result) > width:
            result = result[:width - 1] + [",".join(result[width - 1:])]
        return result

    columns = fit_row(header, expected_width)

    data_records = records[header_index + 1:]

    last_exact = -1
    for index, row in enumerate(data_records):
        if len(row) == expected_width:
            last_exact = index

    if last_exact >= 0:
        retained = []
        for index, row in enumerate(data_records):
            if index > last_exact and len(row) == 1:
                continue
            retained.append(row)
        data_records = retained

    rows = [fit_row(row, expected_width) for row in data_records]
    return {"columns": columns, "rows": rows}
